import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../contexts/AuthContext";
import axios from "axios";

export default function StudentDashboard() {
  const navigate = useNavigate();
  const { user, logout } = useContext(AuthContext);
  const [stats, setStats] = useState({
    totalCandidates: 0,
    totalElections: 0,
    hasVoted: false,
  });

  // Fetch dashboard stats
  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [candidatesRes, electionsRes, votesRes] = await Promise.all([
          axios.get("/api/candidates"),
          axios.get("/api/admin/elections"),
          axios.get("/api/my-votes") // you need an endpoint to check if the student voted
        ]);

        setStats({
          totalCandidates: candidatesRes.data.length,
          totalElections: electionsRes.data.length,
          hasVoted: votesRes.data.hasVoted,
        });
      } catch (err) {
        console.error("Failed to fetch dashboard stats:", err);
      }
    };
    fetchStats();
  }, []);

  const actions = [
    { title: "View Candidates", desc: "Browse the list of approved candidates and securely cast your vote.", path: "/candidates" },
    { title: "Register Candidacy", desc: "Submit your requirements to apply as a candidate.", path: "/register-candidacy" },
    { title: "Election Results", desc: "View real-time turnout and final election results.", path: "/results" },
  ];

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "40px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>

        {/* Header */}
        <header style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "40px",
          backgroundColor: "#fff",
          padding: "15px 25px",
          borderRadius: "12px",
          boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: "15px" }}>
            <img src="/logo.png" alt="iVote Logo" style={{ height: "50px" }} />
            <div>
              <h1 style={{ fontSize: "1.8rem", color: "#007bff", margin: 0 }}>Welcome, {user?.name}</h1>
              <p style={{ margin: 0, color: "#555", fontSize: "0.9rem" }}>Student Dashboard</p>
            </div>
          </div>
          <button
            onClick={() => { logout(); navigate("/login"); }}
            style={{
              padding: "8px 16px",
              backgroundColor: "#ff4d4f",
              color: "#fff",
              border: "none",
              borderRadius: "8px",
              fontWeight: "bold",
              cursor: "pointer",
              transition: "background 0.2s"
            }}
            onMouseEnter={e => e.currentTarget.style.backgroundColor = "#d9363e"}
            onMouseLeave={e => e.currentTarget.style.backgroundColor = "#ff4d4f"}
          >
            Logout
          </button>
        </header>

        {/* Stats Cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "25px", marginBottom: "40px" }}>
          <div style={{ padding: "20px", borderRadius: "12px", background: "#fff", boxShadow: "0 2px 6px rgba(0,0,0,0.05)" }}>
            <h3 style={{ color: "#007bff" }}>Total Candidates</h3>
            <p style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{stats.totalCandidates}</p>
          </div>
          <div style={{ padding: "20px", borderRadius: "12px", background: "#fff", boxShadow: "0 2px 6px rgba(0,0,0,0.05)" }}>
            <h3 style={{ color: "#007bff" }}>Total Elections</h3>
            <p style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{stats.totalElections}</p>
          </div>
          <div style={{ padding: "20px", borderRadius: "12px", background: "#fff", boxShadow: "0 2px 6px rgba(0,0,0,0.05)" }}>
            <h3 style={{ color: "#007bff" }}>Voting Status</h3>
            <p style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{stats.hasVoted ? "Voted ✅" : "Not Voted ❌"}</p>
          </div>
        </div>

        {/* Action Cards */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
          gap: "25px"
        }}>
          {actions.map((a, i) => (
            <div
              key={i}
              onClick={() => navigate(a.path)}
              style={{
                padding: "25px",
                borderRadius: "12px",
                border: "1px solid #e0e6ed",
                background: "#fff",
                boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
                cursor: "pointer",
                transition: "all 0.2s ease-in-out"
              }}
              onMouseEnter={(e) => e.currentTarget.style.boxShadow = "0 6px 16px rgba(0,0,0,0.12)"}
              onMouseLeave={(e) => e.currentTarget.style.boxShadow = "0 2px 6px rgba(0,0,0,0.05)"}
            >
              <h2 style={{ fontSize: "1.25rem", color: "#007bff", marginBottom: "10px" }}>
                {a.title}
              </h2>
              <p style={{ fontSize: "0.95rem", color: "#555", lineHeight: "1.5" }}>
                {a.desc}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
